  'z-index',
  'left',
  'top',
  'width',
  'height',
  'background-color',
  'background-image',
  '--stf-paper',
  'pointer-events',
  'transform',
  'transform-origin',
  'clip-path',
  '-webkit-clip-path',
  'backface-visibility',
  '-webkit-backface-visibility',
